function shuffle(arr){var a=arr.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function load(key,def){try{return JSON.parse(localStorage.getItem(key))??def}catch(e){return def}}
function save(key,val){try{localStorage.setItem(key,JSON.stringify(val))}catch(e){}}
function show(id){['home','game','result'].forEach(function(k){$(k).classList.toggle('hidden',k!==id)});window.scrollTo({top:0,behavior:'smooth'});}
function countByDisc(code){return Q.filter(function(q){return q[0]===code}).length}
function renderDiscs(){var h='<button class="disc '+(state.discipline==='ALL'?'selected':'')+'" data-code="ALL"><span class="emoji">🎲</span><span class="name">Conteúdo misturado</span><span class="count">'+Q.length+' questões</span></button>';Object.keys(DISC).forEach(function(code){h+='<button class="disc '+(state.discipline===code?'selected':'')+'" data-code="'+code+'"><span class="emoji">'+DISC[code][1]+'</span><span class="name">'+DISC[code][0]+'</span><span class="count">'+countByDisc(code)+' questões</span></button>'});$('discs').innerHTML=h;$('discs').querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){state.discipline=b.dataset.code;renderDiscs()})})}
function setupSegments(id,key){$(id).querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){state[key]=key==='mode'?(b.dataset.value==='timed'?'timed':'free'):(b.dataset.value==='all'?'all':Number(b.dataset.value));$(id).querySelectorAll('button').forEach(function(x){x.classList.toggle('active',x===b)})})})}
function rankData(){return load('trilhaDSRank',[])}
function renderRank(){var r=rankData().sort(function(a,b){return b.pct-a.pct}).slice(0,8);if(!r.length){$('rankArea').textContent='Nenhuma rodada concluída ainda.';return}$('rankArea').innerHTML='<table class="rank-table"><thead><tr><th>#</th><th>Nome</th><th>Disciplina</th><th>Acertos</th><th>Resultado</th></tr></thead><tbody>'+r.map(function(x,i){return '<tr><td>'+(i+1)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.discipline)+'</td><td>'+x.correct+'/'+x.total+'</td><td><b>'+x.pct+'%</b></td></tr>'}).join('')+'</tbody></table>';var total=r.reduce(function(a,x){return a+x.correct},0),n=r.reduce(function(a,x){return a+x.total},0);$('overallPct').textContent=n?Math.round(total/n*100)+'%':'—';$('overallFoot').textContent=n?total+' acertos em '+n+' questões no histórico':'Jogue uma rodada para começar'}
function start(){var pool=Q.filter(function(q){return state.discipline==='ALL'||q[0]===state.discipline});if(!pool.length)return;var qty=state.quantity==='all'?pool.length:Math.min(state.quantity,pool.length);var drawn=shuffle(pool.slice()).slice(0,qty);var drawKey=drawn.map(function(q){return Q.indexOf(q)});var previousDraw=load('trilhaDSLastOrder',[]);if(drawKey.length===1&&pool.length>1&&previousDraw.length===1&&drawKey[0]===previousDraw[0]){var alternatives=pool.filter(function(q){return Q.indexOf(q)!==previousDraw[0]});drawn=shuffle(alternatives).slice(0,1);drawKey=drawn.map(function(q){return Q.indexOf(q)})}else if(drawKey.length>1&&JSON.stringify(drawKey)===JSON.stringify(previousDraw)){drawn.push(drawn.shift());drawKey=drawn.map(function(q){return Q.indexOf(q)})}save('trilhaDSLastOrder',drawKey);state.questions=drawn;state.index=0;state.points=0;state.correct=0;state.results=[];state.name=$('studentName').value.trim()||'Estudante';save('trilhaDSName',state.name);show('game');ask()}
function ask(){clearInterval(state.timer);var q=state.questions[state.index];state.answered=false;state.remaining=60;state.currentOptions=shuffle(q[2].map(function(t,i){return {text:t,index:i}}));$('disciplinePill').textContent=state.discipline==='ALL'?'Conteúdo misturado':DISC[state.discipline][0];$('progressPill').textContent=(state.index+1)+' / '+state.questions.length;$('pointsPill').textContent=state.points+' pts';$('progressBar').style.width=(state.index/state.questions.length*100)+'%';$('qTag').textContent=DISC[q[0]][1]+' '+DISC[q[0]][0];$('qText').textContent=q[1];var meta=q[5]||{};if(meta.origem){$('qOrigin').textContent=meta.origem;$('qOrigin').classList.remove('hidden')}else{$('qOrigin').classList.add('hidden')}if(meta.imagem){$('qImage').src=meta.imagem;$('qImage').classList.remove('hidden')}else{$('qImage').removeAttribute('src');$('qImage').classList.add('hidden')}$('options').innerHTML=state.currentOptions.map(function(o,i){return '<button class="option" data-index="'+o.index+'"><span class="letter">'+String.fromCharCode(65+i)+'</span><span>'+esc(o.text)+'</span></button>'}).join('');$('options').querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){answer(Number(b.dataset.index))})});$('feedback').className='feedback hidden';$('feedback').innerHTML='';$('nextBtn').classList.add('hidden');$('progressBar').style.width=(state.index/state.questions.length*100)+'%';$('timerWrap').classList.toggle('hidden',state.mode==='free');$('timerLabel').textContent=state.mode==='free'?'Sem limite de tempo':'60 segundos';$('timerBar').style.width='100%';if(state.mode==='timed'){state.timer=setInterval(function(){state.remaining-=.1;$('timerBar').style.width=Math.max(0,state.remaining/60*100)+'%';$('timerLabel').textContent=Math.ceil(state.remaining)+'s';if(state.remaining<=0){clearInterval(state.timer);answer(-1)}},100)}}
function answer(selected){if(state.answered)return;state.answered=true;clearInterval(state.timer);var q=state.questions[state.index],correct=selected===q[3],gain=correct?(state.mode==='timed'?Math.round(500+500*state.remaining/60):1000):0;if(correct){state.correct++;state.points+=gain}var btns=$('options').querySelectorAll('button');btns.forEach(function(b){b.disabled=true;var idx=Number(b.dataset.index);if(idx===q[3])b.classList.add('correct');else if(idx===selected)b.classList.add('wrong')});var f=$('feedback');f.className='feedback '+(correct?'good':'bad');var meta=q[5]||{};f.innerHTML='<strong>'+(correct?'✓ Resposta correta · +'+gain+' pontos':selected<0?'Tempo esgotado':'Resposta incorreta')+'</strong><div>Gabarito: <b>'+String.fromCharCode(65+state.currentOptions.findIndex(function(o){return o.index===q[3]}))+') '+esc(q[2][q[3]])+'</b></div><p>'+esc(q[4])+'</p>'+(meta.tema?'<div class="cap">Tema: '+esc(meta.tema)+'</div>':'')+(meta.capacidade?'<div class="cap">Capacidade relacionada: '+esc(meta.capacidade)+'</div>':'')+(meta.nota?'<div class="cap">'+esc(meta.nota)+'</div>':'');f.classList.remove('hidden');$('pointsPill').textContent=state.points+' pts';$('nextBtn').textContent=state.index+1===state.questions.length?'Ver resultado →':'Próxima questão →';$('nextBtn').classList.remove('hidden');state.results.push({q:q,selected:selected,correct:correct})}
function finish(){clearInterval(state.timer);var pct=Math.round(state.correct/state.questions.length*100),d=state.discipline==='ALL'?'Conteúdo misturado':DISC[state.discipline][0];$('finalScore').textContent=pct+'%';$('resultTitle').textContent=pct>=80?'Ótimo domínio!':pct>=60?'Bom caminho.':'Continue praticando.';$('resultText').textContent=state.name+', você acertou '+state.correct+' de '+state.questions.length+' questões.';$('resultStats').innerHTML='<span>✓ '+state.correct+' acertos</span><span>× '+(state.questions.length-state.correct)+' erros</span><span>'+state.points+' pontos</span>';$('reviewList').innerHTML='<h3>Revisão da rodada</h3>'+state.results.map(function(r,i){return '<div class="review-item"><b>'+(i+1)+'. '+(r.correct?'✓':'×')+' '+esc(r.q[1])+'</b><span class="hint">'+(r.correct?'Acertou':'Resposta correta: '+esc(r.q[2][r.q[3]]))+'</span></div>'}).join('');var rank=rankData();rank.push({name:state.name,discipline:d,correct:state.correct,total:state.questions.length,pct:pct,points:state.points,date:new Date().toISOString()});save('trilhaDSRank',rank.slice(-30));renderRank();show('result')}
$('startBtn').addEventListener('click',start);$('nextBtn').addEventListener('click',function(){if(state.index+1<state.questions.length){state.index++;ask()}else finish()});$('quitBtn').addEventListener('click',function(){if(confirm('Sair desta rodada? O resultado parcial não será salvo.')){clearInterval(state.timer);show('home')}});$('homeBtn').addEventListener('click',function(){show('home')});$('clearRank').addEventListener('click',function(){if(confirm('Limpar o histórico salvo neste navegador?')){save('trilhaDSRank',[]);renderRank()}});$('themeBtn').addEventListener('click',function(){var t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;save('trilhaDSTheme',t)});
$('studentName').value=load('trilhaDSName','');var savedTheme=load('trilhaDSTheme','light');document.documentElement.dataset.theme=savedTheme;$('totalQ').textContent=Q.length;renderDiscs();setupSegments('modeSeg','mode');setupSegments('qtySeg','quantity');renderRank();
